  },

  async getChatConversationById(conversationId: string) {
    const { data, error } = await supabase
      .from('chat_conversations')
      .select('*')
      .eq('id', conversationId)
      .single();
    return { data, error };
  },

  async ensureChatConversation(conversation: {
    threadKey: string;
    threadType?: string;
    contextType?: string | null;
    contextId?: string | null;
    participantAId: string;
    participantBId: string;
    participantARole: string;
    participantBRole: string;
    participantAName?: string;
    participantBName?: string;
    participantAAvatar?: string;
    participantBAvatar?: string;
    subject?: string | null;
  }) {
    const existing = await supabase
      .from('chat_conversations')
      .select('*')
      .eq('thread_key', conversation.threadKey)
      .maybeSingle();

    if (existing.data) {
      return { data: existing.data, error: existing.error };
    }

    const { data, error } = await supabase
      .from('chat_conversations')
      .insert([{
        thread_key: conversation.threadKey,
        thread_type: conversation.threadType || 'direct',
        context_type: conversation.contextType || null,
        context_id: conversation.contextId || null,
        participant_a_id: conversation.participantAId,
        participant_b_id: conversation.participantBId,
        participant_a_role: conversation.participantARole,
        participant_b_role: conversation.participantBRole,
        participant_a_name: conversation.participantAName || null,
        participant_b_name: conversation.participantBName || null,
        participant_a_avatar: conversation.participantAAvatar || null,
        participant_b_avatar: conversation.participantBAvatar || null,
        subject: conversation.subject || null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }])
      .select()
      .single();

    return { data, error };
  },

  async getChatConversations(userId: string) {
    const { data, error } = await supabase
      .from('chat_conversations')
      .select('*')
      .or(`participant_a_id.eq.${userId},participant_b_id.eq.${userId}`)
      .order('updated_at', { ascending: false });
    return { data, error };
  },

  async getChatMessages(conversationId: string) {
    const { data, error } = await supabase
      .from('chat_messages')
      .select('*')
      .eq('conversation_id', conversationId)
      .order('created_at', { ascending: true });
    return { data, error };
  },

  async sendChatMessage(message: {
    conversationId: string;
    senderId: string;
    receiverId: string;
    senderName: string;
    senderRole: string;
    receiverRole: string;
    message: string;
  }) {
    const timestamp = new Date().toISOString();
    const { data, error } = await supabase
      .from('chat_messages')
      .insert([{
        conversation_id: message.conversationId,
        sender_id: message.senderId,
        receiver_id: message.receiverId,
        sender_name: message.senderName,
        sender_role: message.senderRole,
        receiver_role: message.receiverRole,
        message: message.message,
        read: false,
        created_at: timestamp,
        updated_at: timestamp,
      }])
      .select()
      .single();

    if (!error) {
      const { data: conversation } = await supabase
        .from('chat_conversations')
        .select('*')
        .eq('id', message.conversationId)
        .single();

      if (conversation) {
        const isParticipantA = conversation.participant_a_id === message.senderId;
        const unreadA = isParticipantA ? (conversation.unread_count_a || 0) : (conversation.unread_count_a || 0) + 1;
        const unreadB = !isParticipantA ? (conversation.unread_count_b || 0) : (conversation.unread_count_b || 0) + 1;

        await supabase
          .from('chat_conversations')
          .update({
            last_message_preview: message.message,
            last_message_sender_id: message.senderId,
            last_message_at: timestamp,
            unread_count_a: isParticipantA ? unreadA : unreadA,
            unread_count_b: isParticipantA ? unreadB : unreadB,
            updated_at: timestamp,
          })
          .eq('id', message.conversationId);
      }
    }

    return { data, error };
  },

  async markChatConversationRead(conversationId: string, userId: string) {
    const timestamp = new Date().toISOString();
    const { data: conversation } = await supabase
      .from('chat_conversations')
      .select('*')
      .eq('id', conversationId)
      .single();

    const { data, error } = await supabase
      .from('chat_messages')
      .update({ read: true, read_at: timestamp, updated_at: timestamp })
      .eq('conversation_id', conversationId)
      .neq('sender_id', userId)
      .eq('read', false)
      .select();

    if (conversation) {
      const isParticipantA = conversation.participant_a_id === userId;
      await supabase
        .from('chat_conversations')
        .update({
          unread_count_a: isParticipantA ? 0 : conversation.unread_count_a || 0,
          unread_count_b: isParticipantA ? conversation.unread_count_b || 0 : 0,
          updated_at: timestamp,
        })
        .eq('id', conversationId);
    }

    return { data, error };
  },

  async getUnreadChatCount(userId: string) {
    const { data, error, count } = await supabase
      .from('chat_messages')
      .select('*', { count: 'exact' })
      .eq('receiver_id', userId)
      .eq('read', false);

    return { count, data, error };
  },

  subscribeToChatConversation(conversationId: string, callback: (data: any) => void) {
    const channel = supabase
      .channel(`chat_conversation_${conversationId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'chat_messages',
          filter: `conversation_id=eq.${conversationId}`
        },
        (payload) => callback(payload.new)
      )
      .subscribe();

    return () => supabase.removeChannel(channel);
  },

  subscribeToUserChatThreads(userId: string, callback: () => void) {
    const channel = supabase
      .channel(`chat_threads_${userId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'chat_conversations',
          filter: `participant_a_id=eq.${userId}`,
        },
        () => callback()
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'chat_conversations',
          filter: `participant_b_id=eq.${userId}`,
        },
        () => callback()
      )
      .subscribe();

    return () => supabase.removeChannel(channel);
  },

  // Order operations
  async createOrder(order: any) {
    const { data, error } = await supabase
      .from('orders')
      .insert([order])
      .select()
      .single();
    return { data, error };
  },

  async getOrders(customerId: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('customer_id', customerId)
      .order('created_at', { ascending: false });
    return { data, error };
  },

  // Get all orders with filters
  async getAllOrders(filters?: any) {
    let query = supabase.from('orders').select('*');

    if (filters?.restaurantId) query = query.eq('restaurant_id', filters.restaurantId);
    if (filters?.customerId) query = query.eq('customer_id', filters.customerId);
    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.orderNumber) query = query.eq('order_number', filters.orderNumber);
    if (filters?.customerEmail) query = query.eq('customer_email', filters.customerEmail);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  // Get order by ID
  async getOrderById(orderId: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('id', orderId)
      .single();
    return { data, error };
  },

  // Get order by order number
  async getOrderByNumber(orderNumber: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('order_number', orderNumber)
      .single();
    return { data, error };
  },

  // Get business orders (orders for a specific restaurant)
  async getBusinessOrders(restaurantId: string, filters?: any) {
    let query = supabase.from('orders').select('*').eq('restaurant_id', restaurantId);

    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.startDate) query = query.gte('created_at', filters.startDate);
    if (filters?.endDate) query = query.lte('created_at', filters.endDate);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  // Get pending orders for a business
  async getPendingOrders(restaurantId: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .in('status', ['pending', 'preparing', 'ready', 'on-the-way'])
      .order('created_at', { ascending: true });
    return { data, error };
  },

  // Search orders by customer email
  async searchOrdersByCustomerEmail(customerEmail: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .ilike('customer_email', `%${customerEmail}%`)
      .order('created_at', { ascending: false });
    return { data, error };
  },

  // Get recent orders (last N orders)
  async getRecentOrders(limit: number = 10) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(limit);
    return { data, error };
  },

  async updateOrder(orderId: string, updates: any) {
    const { data, error } = await supabase
      .from('orders')
      .update(updates)
      .eq('id', orderId)
      .select()
      .single();
    return { data, error };
  },

  // Delete order
  async deleteOrder(orderId: string) {
    const { data, error } = await supabase
      .from('orders')
      .delete()
      .eq('id', orderId);
    return { data, error };
  },

  // File uploads
  async uploadProfilePhoto(userId: string, file: File) {
    const fileExt = file.name.split('.').pop();
    const filePath = `${userId}/profile.${fileExt}`;

    const { data, error } = await supabase.storage
      .from('user_profiles')
      .upload(filePath, file, { upsert: true });

    if (error) return { data: null, error };

    const { data: publicUrlData } = supabase.storage
      .from('user_profiles')
      .getPublicUrl(filePath);

    return { data: publicUrlData, error: null };
  },

  async uploadRestaurantImage(restaurantId: string, file: File) {
    const fileExt = file.name.split('.').pop();
    const filePath = `${restaurantId}/image.${fileExt}`;

    const { data, error } = await supabase.storage
      .from('restaurants')
      .upload(filePath, file, { upsert: true });

    if (error) return { data: null, error };

    const { data: publicUrlData } = supabase.storage
      .from('restaurants')
      .getPublicUrl(filePath);

    return { data: publicUrlData, error: null };
  },

  // Order Processing Operations
  async createOrderProcessing(processing: any) {
    const { data, error } = await supabase
      .from('order_processing')
      .insert([processing])
      .select()
      .single();
    return { data, error };
  },

  async getOrderProcessing(orderId: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('order_id', orderId)
      .single();
    return { data, error };
  },

  async getRestaurantProcessing(restaurantId: string, filters?: any) {
    let query = supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId);

    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.startDate) query = query.gte('created_at', filters.startDate);
    if (filters?.endDate) query = query.lte('created_at', filters.endDate);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  async updateOrderProcessingStatus(orderId: string, status: string, updates?: any) {
    const timestamp = new Date().toISOString();
    const statusUpdateMap: { [key: string]: string } = {
      'received': 'received_at',
      'confirmed': 'confirmed_at',
      'preparing': 'preparing_started_at',
      'quality_check': 'quality_check_at',
      'ready': 'ready_at',
      'assigned_rider': 'rider_assigned_at',
      'on_the_way': 'delivery_started_at',
      'delivered': 'delivered_at',
      'completed': 'completed_at',
      'cancelled': 'cancelled_at',
    };

    const updateData: any = {
      status,
      updated_at: timestamp,
      ...updates,
    };

    // Auto-set timestamp field for this status
    const timestampField = statusUpdateMap[status];
    if (timestampField) {
      updateData[timestampField] = timestamp;
    }

    const { data, error } = await supabase
      .from('order_processing')
      .update(updateData)
      .eq('order_id', orderId)
      .select()
      .single();

    return { data, error };
  },

  async getProcessingByStatus(restaurantId: string, status: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .eq('status', status)
      .order('created_at', { ascending: true });

    return { data, error };
  },

  async getActiveProcessing(restaurantId: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .in('status', ['received', 'confirmed', 'preparing', 'quality_check', 'ready', 'assigned_rider', 'on_the_way'])
      .order('created_at', { ascending: true });

    return { data, error };
  },

  async getProcessingHistory(restaurantId: string, limit: number = 50) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .in('status', ['delivered', 'completed', 'cancelled'])
      .order('completed_at', { ascending: false })
      .limit(limit);

    return { data, error };
  },

  async assignRiderToOrder(orderId: string, riderId: string, riderName: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .update({
        assigned_rider_id: riderId,
        assigned_rider_name: riderName,
        updated_at: new Date().toISOString(),
      })
      .eq('order_id', orderId)
      .select()
      .single();

    return { data, error };
  },

  async recordQualityCheck(orderId: string, passed: boolean, issues?: any) {
    const { data, error } = await supabase
      .from('order_processing')
      .update({
        qa_passed: passed,
        quality_issues: issues || null,
        updated_at: new Date().toISOString(),
      })
      .eq('order_id', orderId)
      .select()
      .single();

    return { data, error };
  },

  async getProcessingStats(restaurantId: string, dateRange?: { start: string; end: string }) {
    let query = supabase
      .from('order_processing')
      .select('*', { count: 'exact' })
      .eq('restaurant_id', restaurantId);

    if (dateRange?.start) query = query.gte('created_at', dateRange.start);
    if (dateRange?.end) query = query.lte('created_at', dateRange.end);

    const { data, error, count } = await query;

    if (error) return { data: null, error };

    // Calculate statistics
    const stats = {
      totalOrders: count,
      completed: data?.filter(p => p.status === 'completed').length || 0,
      cancelled: data?.filter(p => p.status === 'cancelled').length || 0,
      averagePrepTime: 0,
      qualityIssues: data?.filter(p => !p.qa_passed).length || 0,
    };

    // Calculate average prep time
    const completedWithTime = data?.filter(p => p.actual_prep_time) || [];
    if (completedWithTime.length > 0) {
      const totalTime = completedWithTime.reduce((sum: number, p: any) => sum + (p.actual_prep_time || 0), 0);
      stats.averagePrepTime = Math.round(totalTime / completedWithTime.length);
    }

    return { data: stats, error: null };
  },

  // Real-time subscription for driver status updates
  subscribeToRideUpdates(rideId: string, callback: (data: any) => void) {
    console.log(` Setting up real-time subscription for ride: ${rideId}`);

    const channel = supabase
      .channel(`ride_${rideId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'ride_requests',
          filter: `id=eq.${rideId}`
        },
        (payload) => {
          console.log(' Real-time update received:', payload);
          callback(payload.new);
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`✅ Real-time subscription active for ride: ${rideId}`);
        } else if (status === 'CHANNEL_ERROR') {
          console.error(`❌ Subscription error for ride: ${rideId}`);
        }
      });

    // Return unsubscribe function
    return () => {
      console.log(` Unsubscribing from ride: ${rideId}`);
      supabase.removeChannel(channel);
    };
  },

  // Subscribe to accepted rides (for driver acceptance in real-time)
  subscribeToAcceptedRides(customerId: string, callback: (data: any) => void) {
    console.log(` Setting up real-time subscription for customer accepted rides: ${customerId}`);

    const channel = supabase
      .channel(`customer_${customerId}_rides`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'ride_requests',
          filter: `customer_id=eq.${customerId}`
        },
        (payload) => {
          // Only notify if driver has been assigned
          if (payload.new.accepted_driver_id) {
            console.log(' Driver accepted ride (real-time):', payload);
            callback(payload.new);
          }
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`✅ Real-time subscription active for customer: ${customerId}`);
        } else if (status === 'CHANNEL_ERROR') {
          console.error(`❌ Subscription error for customer: ${customerId}`);
        }
      });

    return () => {
      console.log(` Unsubscribing from customer rides: ${customerId}`);
      supabase.removeChannel(channel);
    };
  },
};

import { useState, useEffect } from "react";
import { GoogleMap, LoadScript, Marker, InfoWindow } from "@react-google-maps/api";
import {
  Home as HomeIcon, 
  Package, 
  Users, 
  DollarSign, 
  Camera, 
  Navigation,
  Calendar,
  UserCircle,
  MapPin,
  MoreHorizontal,
  Power,
  Car,
  Settings,
  Bell,
  Star,
  X,
  Zap,
  MessageCircle
} from "lucide-react";
import { Link, useNavigate } from "react-router";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Switch } from "../ui/switch";
import { Badge } from "../ui/badge";
import { Input } from "../ui/input";
import { useAuth } from "../../contexts/AuthContext";
import { supabaseHelpers } from "@/lib/supabase";

// Get Google Maps API Key from environment variable
const GOOGLE_MAPS_API_KEY = import.meta.env.VITE_GOOGLE_MAPS_API_KEY || "";
const GOOGLE_MAPS_LIBRARIES = ["places"] as const;

interface IncomingRequest {
  id: string;
  type: 'delivery' | 'shared' | 'private';
  pickup: string;
  dropoff: string;
  payment: 'COD' | 'PREPAID';
  amount: number;
  foodCost?: number;
  passengers?: number;
  waitingPassengers?: number;
}

export default function RiderDashboard() {
  const navigate = useNavigate();
  const { user, updateProfile } = useAuth();
  const [isOnline, setIsOnline] = useState(user?.isOnline || false);
  const [mode, setMode] = useState<'shared' | 'delivery'>('shared');
  const [currentSeats, setCurrentSeats] = useState(user?.currentSeats || 0);
  const [earnings, setEarnings] = useState(450);
  const [activeTrip, setActiveTrip] = useState<IncomingRequest | null>(null);
  const [showServiceTypes, setShowServiceTypes] = useState(false);
  const [showDestination, setShowDestination] = useState(false);
  const [showMore, setShowMore] = useState(false);
  const [selectedServices, setSelectedServices] = useState<string[]>(user?.serviceTypes || ['shared', 'delivery']);
  const [destination, setDestination] = useState('');
  const [totalPendingRequests, setTotalPendingRequests] = useState(0);
  const [hasActiveRide, setHasActiveRide] = useState(false);
  const [activeRideData, setActiveRideData] = useState<any>(null);
  const [unreadMessagesCount, setUnreadMessagesCount] = useState(0);
  const [tripsCompletedCount, setTripsCompletedCount] = useState(0);
  const [mapCenter, setMapCenter] = useState<{ lat: number; lng: number }>({ lat: 14.5995, lng: 120.9842 }); // Default: Manila
  const [selectedMarker, setSelectedMarker] = useState<{ lat: number; lng: number } | null>(null);
  const [isLoadingLocation, setIsLoadingLocation] = useState(true);
  const [locationError, setLocationError] = useState<string | null>(null);

  // Get user's current location on component mount
  useEffect(() => {
    setIsLoadingLocation(true);
    setLocationError(null);

    if ('geolocation' in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setMapCenter({ lat: latitude, lng: longitude });
          setIsLoadingLocation(false);
          console.log('User location:', latitude, longitude);
        },
        (error) => {
          console.warn('Geolocation error:', error.message);
          setLocationError(error.message);
          setIsLoadingLocation(false);
          // Keep default location (Manila) if geolocation fails
        },
        {
          enableHighAccuracy: true,
          timeout: 10000,
          maximumAge: 0
        }
      );
    } else {
      console.warn('Geolocation not supported by browser');
      setLocationError('Geolocation not supported');
      setIsLoadingLocation(false);
    }
  }, []);

  // Persist online status and service types to auth context
  useEffect(() => {
    if (user && updateProfile) {
      updateProfile({
        isOnline,
        serviceTypes: selectedServices,
        currentSeats
      });
    }
  }, [isOnline, selectedServices, currentSeats, user, updateProfile]);

  // Check for active ride in localStorage
  useEffect(() => {
    const checkActiveRide = () => {
      const savedRide = localStorage.getItem('trikeserve_active_ride');
      if (savedRide) {
        try {
          const ride = JSON.parse(savedRide);

          // Only consider it an active ride if status is truly active
          const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];
          if (ride.status && activeStatuses.includes(ride.status)) {
            setHasActiveRide(true);
            setActiveRideData(ride);
          } else {
            // Clear completed or invalid rides
            localStorage.removeItem('trikeserve_active_ride');
            setHasActiveRide(false);
            setActiveRideData(null);
          }
        } catch (error) {
          console.error('Error loading active ride:', error);
          // Clear invalid data
          localStorage.removeItem('trikeserve_active_ride');
          setHasActiveRide(false);
          setActiveRideData(null);
        }
      } else {
        setHasActiveRide(false);
        setActiveRideData(null);
      }
    };

    checkActiveRide();

    // Poll for active ride updates
    const interval = setInterval(checkActiveRide, 2000);

    return () => clearInterval(interval);
  }, []);

  // Load and monitor passenger requests from Supabase (for real-time accuracy)
  useEffect(() => {
    const loadRequests = async () => {
      try {
        // Fetch pending ride requests from Supabase (not localStorage)
        const { data: rideRequests, error: dbError } = await supabaseHelpers.getRideRequests({
          status: 'pending'
        });

        if (dbError) {
          console.error('❌ Error loading requests from database:', dbError);
          setTotalPendingRequests(0);
          return;
        }

        if (rideRequests && rideRequests.length > 0) {
          setTotalPendingRequests(rideRequests.length);
          console.log('✅ Loaded passenger count from Supabase:', rideRequests.length);
        } else {
          setTotalPendingRequests(0);
          console.log(' No pending passenger requests in database');
        }
      } catch (error) {
        console.error('❌ Error loading requests:', error);
        setTotalPendingRequests(0);
      }
    };

    // Load initially
    loadRequests();

    // Poll for updates every 3 seconds (matches PassengerRequests polling interval)
    const interval = setInterval(loadRequests, 3000);

    return () => {
      clearInterval(interval);
    };
  }, []);

  // Count unread messages from passengers
  useEffect(() => {
    const countUnreadMessages = () => {
      let unreadCount = 0;

      // Scan localStorage for all chat keys
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('chat_')) {
          try {
            const messages = JSON.parse(localStorage.getItem(key) || '[]');
            // Count unread messages from passengers (sent by customers)
            const unread = messages.filter((m: any) => 
              m.senderType === 'passenger' && !m.read
            ).length;
            unreadCount += unread;
          } catch (error) {
            console.error('Error counting unread messages:', error);
          }
        }
      }

      setUnreadMessagesCount(unreadCount);
    };

    // Count initially
    countUnreadMessages();

    // Poll for updates every 2 seconds
    const interval = setInterval(countUnreadMessages, 2000);

    // Listen for storage events (cross-tab sync)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key?.startsWith('chat_')) {
        countUnreadMessages();
      }
    };

    window.addEventListener('storage', handleStorageChange);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  // Fetch completed trips count
  useEffect(() => {
    const fetchCompletedTripsCount = async () => {
      try {
        // Get completed rides from database for this driver
        const { data: completedRides, error } = await supabaseHelpers.getRideRequests({
          driverId: user?.id,
          status: 'completed'
        });

        if (error) {
          console.error('❌ Error fetching completed rides:', error);
          return;
        }

        // Also check localStorage for ride history
        const historyKey = `ride_history_${user?.id}`;
        const historyData = localStorage.getItem(historyKey);
        let localCount = 0;
        if (historyData) {
          try {
            localCount = JSON.parse(historyData).filter((r: any) => r.status === 'completed').length;
          } catch (error) {
            console.error('❌ Error parsing ride history:', error);
          }
        }

        // Combine counts (avoid double counting)
        const totalCount = (completedRides?.length || 0) + localCount;
        setTripsCompletedCount(totalCount);

        console.log('✅ Completed trips count:', totalCount);
      } catch (error) {
        console.error('❌ Error fetching completed trips count:', error);
      }
    };

    if (user?.id) {
      fetchCompletedTripsCount();

      // Poll for updates every 10 seconds
      const interval = setInterval(fetchCompletedTripsCount, 10000);
      return () => clearInterval(interval);
    }
  }, [user?.id]);

  const handleCompleteTrip = () => {
    if (activeTrip) {
      setEarnings(prev => prev + activeTrip.amount);
      setActiveTrip(null);
      setCurrentSeats(0);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-[#F8F9FA] relative">
      {/* Full Screen Map */}
      <div className="absolute inset-0">
        {!GOOGLE_MAPS_API_KEY ? (
          <div className="w-full h-full flex items-center justify-center bg-gray-200">
            <div className="text-center">
              <p className="text-xl font-bold text-red-600 mb-4">⚠️ Google Maps API Key Missing</p>
              <p className="text-gray-700 mb-4">To use Google Maps, please:</p>
              <ol className="text-left text-sm text-gray-600 mb-4">
                <li>1. Get a Google Maps API Key from Google Cloud Console</li>
                <li>2. Create a .env.local file in the project root</li>
                <li>3. Add: VITE_GOOGLE_MAPS_API_KEY=your_api_key</li>
                <li>4. Restart the dev server</li>
              </ol>
              <p className="text-xs text-gray-500">Default location shown: Manila, Philippines</p>
            </div>
          </div>
        ) : (
          <LoadScript googleMapsApiKey={GOOGLE_MAPS_API_KEY} libraries={GOOGLE_MAPS_LIBRARIES}>
            <GoogleMap
              mapContainerStyle={{ width: "100%", height: "100%" }}
              center={mapCenter}
              zoom={15}
              options={{
                zoomControl: false,
                fullscreenControl: true,
                streetViewControl: false,
                mapTypeControl: true,
              }}
            >
              {/* Current Location Marker */}
              <Marker
                position={mapCenter}
                onClick={() => setSelectedMarker(mapCenter)}
                title="Your location"
              />

              {/* Info Window for selected marker */}
              {selectedMarker && (
                <InfoWindow
                  position={selectedMarker}
                  onCloseClick={() => setSelectedMarker(null)}
                >
                  <div className="text-sm">
                    <p className="font-bold">Your current location</p>
                    <p className="text-gray-600">
                      {selectedMarker.lat.toFixed(4)}, {selectedMarker.lng.toFixed(4)}
                    </p>
                  </div>
                </InfoWindow>
              )}
            </GoogleMap>
          </LoadScript>
        )}

        {/* Toggle Online/Offline Button */}
        {!activeTrip && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000]">
            <Button
              onClick={() => setIsOnline(!isOnline)}
              className={`${
                isOnline 
                  ? 'bg-[#E11D48] hover:bg-[#BE123C] text-white'
                  : 'bg-[#121212] hover:bg-[#2a2a2a] text-white'
              } px-8 py-3 rounded-full font-bold shadow-xl flex items-center gap-2`}
            >
              {isOnline ? (
                <>
                  <div className="w-3 h-3 rounded-full bg-white animate-pulse" />
                  <span>You're Online</span>
                </>
              ) : (
                <>
                  <Power className="w-5 h-5" />
                  <span>Go Online</span>
                </>
              )}
            </Button>
          </div>
        )}

        {/* Active Trip Card */}
        {activeTrip && (
          <div className="absolute bottom-20 left-0 right-0 z-[1000] p-4">
            <Card className="p-6 bg-white shadow-2xl border-2 border-[#E11D48]">
              <div className="flex items-start justify-between mb-4">
                <div>
                  <Badge className="mb-2 bg-[#E11D48]">
                    {activeTrip.type === 'delivery' ? 'DELIVERY' : activeTrip.type.toUpperCase()}
                  </Badge>
                  <h3 className="font-bold text-lg text-[#121212]">Active Trip</h3>
                </div>
                <Badge variant="outline" className={activeTrip.payment === 'COD' ? 'border-orange-500 text-orange-500' : 'border-green-500 text-green-500'}>
                  {activeTrip.payment}
                </Badge>
              </div>

              <div className="space-y-3 mb-4">
                <div className="flex gap-2">
                  <Navigation className="w-5 h-5 text-[#E11D48] flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs text-[#64748B]">Pickup</p>
                    <p className="font-semibold text-[#121212]">{activeTrip.pickup}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Navigation className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs text-[#64748B]">Drop-off</p>
                    <p className="font-semibold text-[#121212]">{activeTrip.dropoff}</p>
                  </div>
                </div>
              </div>

              {activeTrip.type === 'delivery' && activeTrip.payment === 'COD' && Number(activeTrip.foodCost || 0) > 0 && (
                <div className="bg-orange-50 border border-orange-200 rounded-lg p-3 mb-4">
                  <p className="text-sm font-semibold text-orange-800 mb-1">⚠️ Pay Restaurant First</p>
                  <p className="text-xs text-orange-700">Food Cost: ₱{activeTrip.foodCost?.toFixed(2)}</p>
                  <p className="text-xs text-orange-700">You'll be reimbursed by customer</p>
                </div>
              )}

              <div className="flex gap-2">
                <Button
                  onClick={handleCompleteTrip}
                  className="flex-1 bg-green-600 hover:bg-green-700 text-white uppercase"
                >
                  <Camera className="w-4 h-4 mr-2" />
                  COMPLETE TRIP
                </Button>
              </div>

              <div className="mt-3 text-center">
                <p className="text-sm text-[#64748B]">
                  Delivery Fee: <span className="font-bold text-[#E11D48]">₱{activeTrip.amount.toFixed(2)}</span>
                </p>
              </div>
            </Card>
          </div>
        )}

        {/* Incoming Requests */}
        {/* Removed - requests only shown on Passenger Requests page */}

        {/* Bottom Sheet - Always visible (Quick Actions, Service Types, Destination, Auto Accept, Passenger Requests) */}
        {!activeTrip && (
          <div className="absolute bottom-20 left-0 right-0 z-[999] px-4">
            <Card className="bg-white shadow-xl rounded-t-3xl max-h-[70vh] overflow-y-auto">
              {/* Quick Actions */}
              <div className={`p-6 grid grid-cols-3 gap-4 ${!isOnline ? 'opacity-50 pointer-events-none' : ''}`}>
                <Link to="/rider/service-types" className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors">
                    <Car className="w-7 h-7 text-[#64748B]" />
                  </div>
                  <span className="text-xs font-medium text-[#121212] text-center">Service<br/>Types</span>
                </Link>
                <Link to="/rider/my-destination" className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors">
                    <MapPin className="w-7 h-7 text-[#64748B]" />
                  </div>
                  <span className="text-xs font-medium text-[#121212] text-center">My<br/>Destination</span>
                </Link>
                <Link to="/rider/auto-accept" className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors">
                    <Zap className="w-7 h-7 text-[#64748B]" />
                  </div>
                  <span className="text-xs font-medium text-[#121212] text-center">Auto<br/>Accept</span>
                </Link>
              </div>

              {/* View All Passenger Requests Card - Always visible, button disabled when offline */}
              <div className="border-t border-gray-200 px-6 py-6">
                <div className="flex flex-col items-center text-center">
                  {/* Header */}
                  <h3 className="font-bold text-lg text-[#121212] mb-6">PASSENGER REQUESTS</h3>

                  {/* Icon and Text Section */}
                  <div className={`flex items-center justify-center gap-4 mb-6 ${!isOnline ? 'opacity-50' : ''}`}>
                    {/* Green Icon Circle */}
                    <div className="w-16 h-16 rounded-full bg-[#10B981] flex items-center justify-center flex-shrink-0">
                      <Users className="w-8 h-8 text-white" />
                    </div>

                    {/* Text Content */}
                    <div className="text-left">
                      <p className="text-sm font-semibold text-[#121212] mb-1">{totalPendingRequests} passengers waiting</p>
                      <p className="text-xs text-[#64748B]">Looking for tricycle<br/>service nearby</p>
                    </div>
                  </div>

                  {/* View All Button - Disabled when offline */}
                  {isOnline ? (
                    <Link to="/rider/passenger-requests" className="w-full">
                      <Button className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white font-bold">
                        View All Passenger Requests
                      </Button>
                    </Link>
                  ) : (
                    <Button disabled className="w-full bg-gray-300 text-gray-500 font-bold cursor-not-allowed">
                      View All Passenger Requests
                    </Button>
                  )}
                </div>
              </div>


              {showServiceTypes && (
                <div className="border-t border-gray-200 p-4 space-y-3">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-bold text-[#121212]">Service Types</h3>
                    <button onClick={() => setShowServiceTypes(false)}>
                      <X className="w-5 h-5 text-[#64748B]" />
                    </button>
                  </div>
                  <p className="text-sm text-[#64748B] mb-3">
                    Select which service types you want to accept
                  </p>
                  <div className="space-y-2">
                    {/* Delivery */}
                    <div
                      onClick={() => {
                        if (selectedServices.includes('delivery')) {
                          setSelectedServices(selectedServices.filter(s => s !== 'delivery'));
                        } else {
                          setSelectedServices([...selectedServices, 'delivery']);
                        }
                      }}
                      className={`flex items-center justify-between p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedServices.includes('delivery')
                          ? 'border-[#E11D48] bg-red-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Package className="w-5 h-5 text-[#E11D48]" />
                        <div>
                          <p className="font-semibold text-[#121212]">Delivery</p>
                          <p className="text-xs text-[#64748B]">Food & package delivery</p>
                        </div>
                      </div>
                      <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                        selectedServices.includes('delivery')
                          ? 'bg-[#E11D48] border-[#E11D48]'
                          : 'border-gray-300'
                      }`}>
                        {selectedServices.includes('delivery') && (
                          <div className="w-2 h-2 bg-white rounded-sm" />
                        )}
                      </div>
                    </div>

                    {/* Ride Share (Sasabay) */}
                    <div
                      onClick={() => {
                        if (selectedServices.includes('shared')) {
                          setSelectedServices(selectedServices.filter(s => s !== 'shared'));
                        } else {
                          setSelectedServices([...selectedServices, 'shared']);
                        }
                      }}
                      className={`flex items-center justify-between p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedServices.includes('shared')
                          ? 'border-[#E11D48] bg-red-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Users className="w-5 h-5 text-[#E11D48]" />
                        <div>
                          <p className="font-semibold text-[#121212]">Ride Share</p>
                          <p className="text-xs text-[#64748B]">Shared rides with other passengers</p>
                        </div>
                      </div>
                      <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                        selectedServices.includes('shared')
                          ? 'bg-[#E11D48] border-[#E11D48]'
                          : 'border-gray-300'
                      }`}>
                        {selectedServices.includes('shared') && (
                          <div className="w-2 h-2 bg-white rounded-sm" />
                        )}
                      </div>
                    </div>

                    {/* Private Ride (Pakyaw) */}
                    <div
                      onClick={() => {
                        if (selectedServices.includes('private')) {
                          setSelectedServices(selectedServices.filter(s => s !== 'private'));
                        } else {
                          setSelectedServices([...selectedServices, 'private']);
                        }
                      }}
                      className={`flex items-center justify-between p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedServices.includes('private')
                          ? 'border-[#E11D48] bg-red-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Car className="w-5 h-5 text-[#E11D48]" />
                        <div>
                          <p className="font-semibold text-[#121212]">Private Ride</p>
                          <p className="text-xs text-[#64748B]">Exclusive rides, no sharing</p>
                        </div>
                      </div>
                      <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                        selectedServices.includes('private')
                          ? 'bg-[#E11D48] border-[#E11D48]'
                          : 'border-gray-300'
                      }`}>
                        {selectedServices.includes('private') && (
                          <div className="w-2 h-2 bg-white rounded-sm" />
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Seat management removed from quick actions */}

                  <Button
                    onClick={() => setShowServiceTypes(false)}
                    className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase"
                  >
                    Save Service Types
                  </Button>
                </div>
              )}

              {/* My Destination Section */}
              {showDestination && (
                <div className="border-t border-gray-200 p-4 space-y-3">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-bold text-[#121212]">My Destination</h3>
                    <button onClick={() => setShowDestination(false)}>
                      <X className="w-5 h-5 text-[#64748B]" />
                    </button>
                  </div>
                  <Input
                    value={destination}
                    onChange={(e) => setDestination(e.target.value)}
                    placeholder="Enter your destination"
                    className="w-full"
                  />
                  <Button className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase">
                    Set Destination
                  </Button>
                </div>
              )}

              {/* More Options Section */}
              {showMore && (
                <div className="border-t border-gray-200 p-4 space-y-3">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-bold text-[#121212]">More Options</h3>
                    <button onClick={() => setShowMore(false)}>
                      <X className="w-5 h-5 text-[#64748B]" />
                    </button>
                  </div>
                  <div className="space-y-2">
                    <Button variant="outline" className="w-full justify-center">
                      <Settings className="w-4 h-4 mr-2" />
                      Settings
                    </Button>
                    <Button variant="outline" className="w-full justify-center">
                      <Bell className="w-4 h-4 mr-2" />
                      Notifications
                    </Button>
                  </div>
                </div>
              )}
            </Card>
          </div>
        )}
      </div>

      {/* Bottom Navigation - Fixed */}
      <div className="absolute bottom-0 left-0 right-0 bg-white border-t-2 border-[#CBD5E1] z-[1000]">
        <div className="px-4 py-3 flex justify-around items-center">
          <Button variant="ghost" className="flex flex-col items-center gap-1">
            <HomeIcon className="w-5 h-5 text-[#00A854]" />
            <span className="text-xs font-semibold text-[#00A854]">Home</span>
          </Button>
          <Link to="/rider/earnings">
            <Button variant="ghost" className="flex flex-col items-center gap-1">
              <DollarSign className="w-5 h-5 text-[#64748B]" />
              <span className="text-xs text-[#64748B]">Earnings</span>
            </Button>
          </Link>
          <Link to="/rider/messages">
            <Button variant="ghost" className="flex flex-col items-center gap-1 relative">
              <MessageCircle className="w-5 h-5 text-[#64748B]" />
              <span className="text-xs text-[#64748B]">Messages</span>
              {unreadMessagesCount > 0 && (
                <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#E11D48] rounded-full border-2 border-white flex items-center justify-center">
                  <div className="w-2 h-2 bg-white rounded-full animate-pulse" />
                </div>
              )}
            </Button>
          </Link>
          <Link to="/rider/profile">
            <Button variant="ghost" className="flex flex-col items-center gap-1">
              <UserCircle className="w-5 h-5 text-[#64748B]" />
              <span className="text-xs text-[#64748B]">Profile</span>
            </Button>
          </Link>
        </div>
      </div>

      {/* Active Ride Floating Icon */}
      {hasActiveRide && activeRideData && (
        <div 
          onClick={() => navigate('/rider/active-ride')}
          className="fixed bottom-24 right-4 z-[1500] cursor-pointer animate-bounce hover:animate-none"
        >
          <div className="bg-[#E11D48] text-white rounded-full w-16 h-16 flex items-center justify-center shadow-2xl border-4 border-white hover:scale-110 transition-transform">
            <div className="text-center">
              <p className="text-2xl">{activeRideData.customerPhoto || ''}</p>
            </div>
          </div>
          <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#10B981] rounded-full border-2 border-white flex items-center justify-center">
            <div className="w-2 h-2 bg-white rounded-full animate-pulse" />
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { GoogleMap, LoadScript, Marker, InfoWindow } from "@react-google-maps/api";
import {
  Home as HomeIcon, 
  Package, 
  Users, 
  DollarSign, 
  Camera, 
  Navigation,
  Calendar,
  UserCircle,
  MapPin,
  MoreHorizontal,
  Power,
  Car,
  Settings,
  Bell,
  Star,
  X,
  Zap,
  MessageCircle
} from "lucide-react";
import { Link, useNavigate } from "react-router";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Switch } from "../ui/switch";
import { Badge } from "../ui/badge";
import { Input } from "../ui/input";
import { useAuth } from "../../contexts/AuthContext";
import { supabaseHelpers } from "@/lib/supabase";

// Get Google Maps API Key from environment variable
const GOOGLE_MAPS_API_KEY = import.meta.env.VITE_GOOGLE_MAPS_API_KEY || "";

// Debug: print runtime API key (helps confirm import.meta.env is available at runtime)
// Remove this log once you've verified the environment value
console.log('DEBUG: VITE_GOOGLE_MAPS_API_KEY =', GOOGLE_MAPS_API_KEY);
const GOOGLE_MAPS_LIBRARIES = ["places"] as const;

interface IncomingRequest {
  id: string;
  type: 'delivery' | 'shared' | 'private';
  pickup: string;
  dropoff: string;
  payment: 'COD' | 'PREPAID';
  amount: number;
  foodCost?: number;
  passengers?: number;
  waitingPassengers?: number;
}

export default function RiderDashboard() {
  const navigate = useNavigate();
  const { user, updateProfile } = useAuth();
  const [isOnline, setIsOnline] = useState(user?.isOnline || false);
  const [mode, setMode] = useState<'shared' | 'delivery'>('shared');
  const [currentSeats, setCurrentSeats] = useState(user?.currentSeats || 0);
  const [earnings, setEarnings] = useState(450);
  const [activeTrip, setActiveTrip] = useState<IncomingRequest | null>(null);
  const [showServiceTypes, setShowServiceTypes] = useState(false);
  const [showDestination, setShowDestination] = useState(false);
  const [showMore, setShowMore] = useState(false);
  const [selectedServices, setSelectedServices] = useState<string[]>(user?.serviceTypes || ['shared', 'delivery']);
  const [destination, setDestination] = useState('');
  const [totalPendingRequests, setTotalPendingRequests] = useState(0);
  const [hasActiveRide, setHasActiveRide] = useState(false);
  const [activeRideData, setActiveRideData] = useState<any>(null);
  const [unreadMessagesCount, setUnreadMessagesCount] = useState(0);
  const [tripsCompletedCount, setTripsCompletedCount] = useState(0);
  const [mapCenter, setMapCenter] = useState<{ lat: number; lng: number }>({ lat: 14.5995, lng: 120.9842 }); // Default: Manila
  const [selectedMarker, setSelectedMarker] = useState<{ lat: number; lng: number } | null>(null);
  const [isLoadingLocation, setIsLoadingLocation] = useState(true);
  const [locationError, setLocationError] = useState<string | null>(null);

  // Get user's current location on component mount
  useEffect(() => {
    setIsLoadingLocation(true);
    setLocationError(null);

    if ('geolocation' in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setMapCenter({ lat: latitude, lng: longitude });
          setIsLoadingLocation(false);
          console.log('User location:', latitude, longitude);
        },
        (error) => {
          console.warn('Geolocation error:', error.message);
          setLocationError(error.message);
          setIsLoadingLocation(false);
          // Keep default location (Manila) if geolocation fails
        },
        {
          enableHighAccuracy: true,
          timeout: 10000,
          maximumAge: 0
        }
      );
    } else {
      console.warn('Geolocation not supported by browser');
      setLocationError('Geolocation not supported');
      setIsLoadingLocation(false);
    }
  }, []);

  // Persist online status and service types to auth context
  useEffect(() => {
    if (user && updateProfile) {
      updateProfile({
        isOnline,
        serviceTypes: selectedServices,
        currentSeats
      });
    }
  }, [isOnline, selectedServices, currentSeats, user, updateProfile]);

  // Check for active ride in localStorage
  useEffect(() => {
    const checkActiveRide = () => {
      const savedRide = localStorage.getItem('trikeserve_active_ride');
      if (savedRide) {
        try {
          const ride = JSON.parse(savedRide);

          // Only consider it an active ride if status is truly active
          const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];
          if (ride.status && activeStatuses.includes(ride.status)) {
            setHasActiveRide(true);
            setActiveRideData(ride);
          } else {
            // Clear completed or invalid rides
            localStorage.removeItem('trikeserve_active_ride');
            setHasActiveRide(false);
            setActiveRideData(null);
          }
        } catch (error) {
          console.error('Error loading active ride:', error);
          // Clear invalid data
          localStorage.removeItem('trikeserve_active_ride');
          setHasActiveRide(false);
          setActiveRideData(null);
        }
      } else {
        setHasActiveRide(false);
        setActiveRideData(null);
      }
    };

    checkActiveRide();

    // Poll for active ride updates
    const interval = setInterval(checkActiveRide, 2000);

    return () => clearInterval(interval);
  }, []);

  // Load and monitor passenger requests from Supabase (for real-time accuracy)
  useEffect(() => {
    const loadRequests = async () => {
      try {
        // Fetch pending ride requests from Supabase (not localStorage)
        const { data: rideRequests, error: dbError } = await supabaseHelpers.getRideRequests({
          status: 'pending'
        });

        if (dbError) {
          console.error('❌ Error loading requests from database:', dbError);
          setTotalPendingRequests(0);
          return;
        }

        if (rideRequests && rideRequests.length > 0) {
          setTotalPendingRequests(rideRequests.length);
          console.log('✅ Loaded passenger count from Supabase:', rideRequests.length);
        } else {
          setTotalPendingRequests(0);
          console.log(' No pending passenger requests in database');
        }
      } catch (error) {
        console.error('❌ Error loading requests:', error);
        setTotalPendingRequests(0);
      }
    };

    // Load initially
    loadRequests();

    // Poll for updates every 3 seconds (matches PassengerRequests polling interval)
    const interval = setInterval(loadRequests, 3000);

    return () => {
      clearInterval(interval);
    };
  }, []);

  // Count unread messages from passengers
  useEffect(() => {
    const countUnreadMessages = () => {
      let unreadCount = 0;

      // Scan localStorage for all chat keys
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('chat_')) {
          try {
            const messages = JSON.parse(localStorage.getItem(key) || '[]');
            // Count unread messages from passengers (sent by customers)
            const unread = messages.filter((m: any) => 
              m.senderType === 'passenger' && !m.read
            ).length;
            unreadCount += unread;
          } catch (error) {
            console.error('Error counting unread messages:', error);
          }
        }
      }

      setUnreadMessagesCount(unreadCount);
    };

    // Count initially
    countUnreadMessages();

    // Poll for updates every 2 seconds
    const interval = setInterval(countUnreadMessages, 2000);

    // Listen for storage events (cross-tab sync)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key?.startsWith('chat_')) {
        countUnreadMessages();
      }
    };

    window.addEventListener('storage', handleStorageChange);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  // Fetch completed trips count
  useEffect(() => {
    const fetchCompletedTripsCount = async () => {
      try {
        // Get completed rides from database for this driver
        const { data: completedRides, error } = await supabaseHelpers.getRideRequests({
          driverId: user?.id,
          status: 'completed'
        });

        if (error) {
          console.error('❌ Error fetching completed rides:', error);
          return;
        }

        // Also check localStorage for ride history
        const historyKey = `ride_history_${user?.id}`;
        const historyData = localStorage.getItem(historyKey);
        let localCount = 0;
        if (historyData) {
          try {
            localCount = JSON.parse(historyData).filter((r: any) => r.status === 'completed').length;
          } catch (error) {
            console.error('❌ Error parsing ride history:', error);
          }
        }

        // Combine counts (avoid double counting)
        const totalCount = (completedRides?.length || 0) + localCount;
        setTripsCompletedCount(totalCount);

        console.log('✅ Completed trips count:', totalCount);
      } catch (error) {
        console.error('❌ Error fetching completed trips count:', error);
      }
    };

    if (user?.id) {
      fetchCompletedTripsCount();

      // Poll for updates every 10 seconds
      const interval = setInterval(fetchCompletedTripsCount, 10000);
      return () => clearInterval(interval);
    }
  }, [user?.id]);

  const handleCompleteTrip = () => {
    if (activeTrip) {
      setEarnings(prev => prev + activeTrip.amount);
      setActiveTrip(null);
      setCurrentSeats(0);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-[#F8F9FA] relative">
      {/* Full Screen Map */}
      <div className="absolute inset-0">
        {!GOOGLE_MAPS_API_KEY ? (
          <div className="w-full h-full flex items-center justify-center bg-gray-200">
            <div className="text-center">
              <p className="text-xl font-bold text-red-600 mb-4">⚠️ Google Maps API Key Missing</p>
              <p className="text-gray-700 mb-4">To use Google Maps, please:</p>
              <ol className="text-left text-sm text-gray-600 mb-4">
                <li>1. Get a Google Maps API Key from Google Cloud Console</li>
                <li>2. Create a .env.local file in the project root</li>
                <li>3. Add: VITE_GOOGLE_MAPS_API_KEY=your_api_key</li>
                <li>4. Restart the dev server</li>
              </ol>
              <p className="text-xs text-gray-500">Default location shown: Manila, Philippines</p>
            </div>
          </div>
        ) : (
          <LoadScript googleMapsApiKey={GOOGLE_MAPS_API_KEY} libraries={GOOGLE_MAPS_LIBRARIES}>
            <GoogleMap
              mapContainerStyle={{ width: "100%", height: "100%" }}
              center={mapCenter}
              zoom={15}
              options={{
                zoomControl: false,
                fullscreenControl: true,
                streetViewControl: false,
                mapTypeControl: true,
              }}
            >
              {/* Current Location Marker */}
              <Marker
                position={mapCenter}
                onClick={() => setSelectedMarker(mapCenter)}
                title="Your location"
              />

              {/* Info Window for selected marker */}
              {selectedMarker && (
                <InfoWindow
                  position={selectedMarker}
                  onCloseClick={() => setSelectedMarker(null)}
                >
                  <div className="text-sm">
                    <p className="font-bold">Your current location</p>
                    <p className="text-gray-600">
                      {selectedMarker.lat.toFixed(4)}, {selectedMarker.lng.toFixed(4)}
                    </p>
                  </div>
                </InfoWindow>
              )}
            </GoogleMap>
          </LoadScript>
        )}

        {/* Toggle Online/Offline Button */}
        {!activeTrip && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000]">
            <Button
              onClick={() => setIsOnline(!isOnline)}
              className={`${
                isOnline 
                  ? 'bg-[#E11D48] hover:bg-[#BE123C] text-white'
                  : 'bg-[#121212] hover:bg-[#2a2a2a] text-white'
              } px-8 py-3 rounded-full font-bold shadow-xl flex items-center gap-2`}
            >
              {isOnline ? (
                <>
                  <div className="w-3 h-3 rounded-full bg-white animate-pulse" />
                  <span>You're Online</span>
                </>
              ) : (
                <>
                  <Power className="w-5 h-5" />
                  <span>Go Online</span>
                </>
              )}
            </Button>
          </div>
        )}

        {/* Active Trip Card */}
        {activeTrip && (
          <div className="absolute bottom-20 left-0 right-0 z-[1000] p-4">
            <Card className="p-6 bg-white shadow-2xl border-2 border-[#E11D48]">
              <div className="flex items-start justify-between mb-4">
                <div>
                  <Badge className="mb-2 bg-[#E11D48]">
                    {activeTrip.type === 'delivery' ? 'DELIVERY' : activeTrip.type.toUpperCase()}
                  </Badge>
                  <h3 className="font-bold text-lg text-[#121212]">Active Trip</h3>
                </div>
                <Badge variant="outline" className={activeTrip.payment === 'COD' ? 'border-orange-500 text-orange-500' : 'border-green-500 text-green-500'}>
                  {activeTrip.payment}
                </Badge>
              </div>

              <div className="space-y-3 mb-4">
                <div className="flex gap-2">
                  <Navigation className="w-5 h-5 text-[#E11D48] flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs text-[#64748B]">Pickup</p>
                    <p className="font-semibold text-[#121212]">{activeTrip.pickup}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Navigation className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs text-[#64748B]">Drop-off</p>
                    <p className="font-semibold text-[#121212]">{activeTrip.dropoff}</p>
                  </div>
                </div>
              </div>

              {activeTrip.type === 'delivery' && activeTrip.payment === 'COD' && Number(activeTrip.foodCost || 0) > 0 && (
                <div className="bg-orange-50 border border-orange-200 rounded-lg p-3 mb-4">
                  <p className="text-sm font-semibold text-orange-800 mb-1">⚠️ Pay Restaurant First</p>
                  <p className="text-xs text-orange-700">Food Cost: ₱{activeTrip.foodCost?.toFixed(2)}</p>
                  <p className="text-xs text-orange-700">You'll be reimbursed by customer</p>
                </div>
              )}

              <div className="flex gap-2">
                <Button
                  onClick={handleCompleteTrip}
                  className="flex-1 bg-green-600 hover:bg-green-700 text-white uppercase"
                >
                  <Camera className="w-4 h-4 mr-2" />
                  COMPLETE TRIP
                </Button>
              </div>

              <div className="mt-3 text-center">
                <p className="text-sm text-[#64748B]">
                  Delivery Fee: <span className="font-bold text-[#E11D48]">₱{activeTrip.amount.toFixed(2)}</span>
                </p>
              </div>
            </Card>
          </div>
        )}

        {/* Incoming Requests */}
        {/* Removed - requests only shown on Passenger Requests page */}

        {/* Bottom Sheet - Always visible (Quick Actions, Service Types, Destination, Auto Accept, Passenger Requests) */}
        {!activeTrip && (
          <div className="absolute bottom-20 left-0 right-0 z-[999] px-4">
            <Card className="bg-white shadow-xl rounded-t-3xl max-h-[70vh] overflow-y-auto">
              {/* Quick Actions */}
              <div className={`p-6 grid grid-cols-3 gap-4 ${!isOnline ? 'opacity-50 pointer-events-none' : ''}`}>
                <Link to="/rider/service-types" className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors">
                    <Car className="w-7 h-7 text-[#64748B]" />
                  </div>
                  <span className="text-xs font-medium text-[#121212] text-center">Service<br/>Types</span>
                </Link>
                <Link to="/rider/my-destination" className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors">
                    <MapPin className="w-7 h-7 text-[#64748B]" />
                  </div>
                  <span className="text-xs font-medium text-[#121212] text-center">My<br/>Destination</span>
                </Link>
                <Link to="/rider/auto-accept" className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors">
                    <Zap className="w-7 h-7 text-[#64748B]" />
                  </div>
                  <span className="text-xs font-medium text-[#121212] text-center">Auto<br/>Accept</span>
                </Link>
              </div>

              {/* View All Passenger Requests Card - Always visible, button disabled when offline */}
              <div className="border-t border-gray-200 px-6 py-6">
                <div className="flex flex-col items-center text-center">
                  {/* Header */}
                  <h3 className="font-bold text-lg text-[#121212] mb-6">PASSENGER REQUESTS</h3>

                  {/* Icon and Text Section */}
                  <div className={`flex items-center justify-center gap-4 mb-6 ${!isOnline ? 'opacity-50' : ''}`}>
                    {/* Green Icon Circle */}
                    <div className="w-16 h-16 rounded-full bg-[#10B981] flex items-center justify-center flex-shrink-0">
                      <Users className="w-8 h-8 text-white" />
                    </div>

                    {/* Text Content */}
                    <div className="text-left">
                      <p className="text-sm font-semibold text-[#121212] mb-1">{totalPendingRequests} passengers waiting</p>
                      <p className="text-xs text-[#64748B]">Looking for tricycle<br/>service nearby</p>
                    </div>
                  </div>

                  {/* View All Button - Disabled when offline */}
                  {isOnline ? (
                    <Link to="/rider/passenger-requests" className="w-full">
                      <Button className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white font-bold">
                        View All Passenger Requests
                      </Button>
                    </Link>
                  ) : (
                    <Button disabled className="w-full bg-gray-300 text-gray-500 font-bold cursor-not-allowed">
                      View All Passenger Requests
                    </Button>
                  )}
                </div>
              </div>


              {showServiceTypes && (
                <div className="border-t border-gray-200 p-4 space-y-3">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-bold text-[#121212]">Service Types</h3>
                    <button onClick={() => setShowServiceTypes(false)}>
                      <X className="w-5 h-5 text-[#64748B]" />
                    </button>
                  </div>
                  <p className="text-sm text-[#64748B] mb-3">
                    Select which service types you want to accept
                  </p>
                  <div className="space-y-2">
                    {/* Delivery */}
                    <div
                      onClick={() => {
                        if (selectedServices.includes('delivery')) {
                          setSelectedServices(selectedServices.filter(s => s !== 'delivery'));
                        } else {
                          setSelectedServices([...selectedServices, 'delivery']);
                        }
                      }}
                      className={`flex items-center justify-between p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedServices.includes('delivery')
                          ? 'border-[#E11D48] bg-red-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Package className="w-5 h-5 text-[#E11D48]" />
                        <div>
                          <p className="font-semibold text-[#121212]">Delivery</p>
                          <p className="text-xs text-[#64748B]">Food & package delivery</p>
                        </div>
                      </div>
                      <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                        selectedServices.includes('delivery')
                          ? 'bg-[#E11D48] border-[#E11D48]'
                          : 'border-gray-300'
                      }`}>
                        {selectedServices.includes('delivery') && (
                          <div className="w-2 h-2 bg-white rounded-sm" />
                        )}
                      </div>
                    </div>

                    {/* Ride Share (Sasabay) */}
                    <div
                      onClick={() => {
                        if (selectedServices.includes('shared')) {
                          setSelectedServices(selectedServices.filter(s => s !== 'shared'));
                        } else {
                          setSelectedServices([...selectedServices, 'shared']);
                        }
                      }}
                      className={`flex items-center justify-between p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedServices.includes('shared')
                          ? 'border-[#E11D48] bg-red-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Users className="w-5 h-5 text-[#E11D48]" />
                        <div>
                          <p className="font-semibold text-[#121212]">Ride Share</p>
                          <p className="text-xs text-[#64748B]">Shared rides with other passengers</p>
                        </div>
                      </div>
                      <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                        selectedServices.includes('shared')
                          ? 'bg-[#E11D48] border-[#E11D48]'
                          : 'border-gray-300'
                      }`}>
                        {selectedServices.includes('shared') && (
                          <div className="w-2 h-2 bg-white rounded-sm" />
                        )}
                      </div>
                    </div>

                    {/* Private Ride (Pakyaw) */}
                    <div
                      onClick={() => {
                        if (selectedServices.includes('private')) {
                          setSelectedServices(selectedServices.filter(s => s !== 'private'));
                        } else {
                          setSelectedServices([...selectedServices, 'private']);
                        }
                      }}
                      className={`flex items-center justify-between p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedServices.includes('private')
                          ? 'border-[#E11D48] bg-red-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Car className="w-5 h-5 text-[#E11D48]" />
                        <div>
                          <p className="font-semibold text-[#121212]">Private Ride</p>
                          <p className="text-xs text-[#64748B]">Exclusive rides, no sharing</p>
                        </div>
                      </div>
                      <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                        selectedServices.includes('private')
                          ? 'bg-[#E11D48] border-[#E11D48]'
                          : 'border-gray-300'
                      }`}>
                        {selectedServices.includes('private') && (
                          <div className="w-2 h-2 bg-white rounded-sm" />
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Seat management removed from quick actions */}

                  <Button
                    onClick={() => setShowServiceTypes(false)}
                    className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase"
                  >
                    Save Service Types
                  </Button>
                </div>
              )}

              {/* My Destination Section */}
              {showDestination && (
                <div className="border-t border-gray-200 p-4 space-y-3">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-bold text-[#121212]">My Destination</h3>
                    <button onClick={() => setShowDestination(false)}>
                      <X className="w-5 h-5 text-[#64748B]" />
                    </button>
                  </div>
                  <Input
                    value={destination}
                    onChange={(e) => setDestination(e.target.value)}
                    placeholder="Enter your destination"
                    className="w-full"
                  />
                  <Button className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase">
                    Set Destination
                  </Button>
                </div>
              )}

              {/* More Options Section */}
              {showMore && (
                <div className="border-t border-gray-200 p-4 space-y-3">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-bold text-[#121212]">More Options</h3>
                    <button onClick={() => setShowMore(false)}>
                      <X className="w-5 h-5 text-[#64748B]" />
                    </button>
                  </div>
                  <div className="space-y-2">
                    <Button variant="outline" className="w-full justify-center">
                      <Settings className="w-4 h-4 mr-2" />
                      Settings
                    </Button>
                    <Button variant="outline" className="w-full justify-center">
                      <Bell className="w-4 h-4 mr-2" />
                      Notifications
                    </Button>
                  </div>
                </div>
              )}
            </Card>
          </div>
        )}
      </div>

      {/* Bottom Navigation - Fixed */}
      <div className="absolute bottom-0 left-0 right-0 bg-white border-t-2 border-[#CBD5E1] z-[1000]">
        <div className="px-4 py-3 flex justify-around items-center">
          <Button variant="ghost" className="flex flex-col items-center gap-1">
            <HomeIcon className="w-5 h-5 text-[#00A854]" />
            <span className="text-xs font-semibold text-[#00A854]">Home</span>
          </Button>
          <Link to="/rider/earnings">
            <Button variant="ghost" className="flex flex-col items-center gap-1">
              <DollarSign className="w-5 h-5 text-[#64748B]" />
              <span className="text-xs text-[#64748B]">Earnings</span>
            </Button>
          </Link>
          <Link to="/rider/messages">
            <Button variant="ghost" className="flex flex-col items-center gap-1 relative">
              <MessageCircle className="w-5 h-5 text-[#64748B]" />
              <span className="text-xs text-[#64748B]">Messages</span>
              {unreadMessagesCount > 0 && (
                <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#E11D48] rounded-full border-2 border-white flex items-center justify-center">
                  <div className="w-2 h-2 bg-white rounded-full animate-pulse" />
                </div>
              )}
            </Button>
          </Link>
          <Link to="/rider/profile">
            <Button variant="ghost" className="flex flex-col items-center gap-1">
              <UserCircle className="w-5 h-5 text-[#64748B]" />
              <span className="text-xs text-[#64748B]">Profile</span>
            </Button>
          </Link>
        </div>
      </div>

      {/* Active Ride Floating Icon */}
      {hasActiveRide && activeRideData && (
        <div 
          onClick={() => navigate('/rider/active-ride')}
          className="fixed bottom-24 right-4 z-[1500] cursor-pointer animate-bounce hover:animate-none"
        >
          <div className="bg-[#E11D48] text-white rounded-full w-16 h-16 flex items-center justify-center shadow-2xl border-4 border-white hover:scale-110 transition-transform">
            <div className="text-center">
              <p className="text-2xl">{activeRideData.customerPhoto || ''}</p>
            </div>
          </div>
          <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#10B981] rounded-full border-2 border-white flex items-center justify-center">
            <div className="w-2 h-2 bg-white rounded-full animate-pulse" />
          </div>
        </div>
      )}
    </div>
  );
}
